// Note: The index.js files inside src/locales are dynamically generated
// by the pullTranslations.sh script

function addLocales(newLocales) {
  src_debugger(`Adding locales ${newLocales}`, 'info');
  let resourceBundle = [];
  Object.keys(newLocales).map(key => {
    Object.keys(newLocales[key]).map(namespace => {
      const locale = newLocales[key][namespace];
      resourceBundle.push({
        key,
        namespace,
        locale
      });
      i18next/* default */.Z.addResourceBundle(key, namespace, locale, true, true);
    });
  });
  src_debugger(`Locales added successfully`, 'info');
  src_debugger(resourceBundle, 'info');
}

